// Helper to convert a PDF presentation into the standard 5-slide Goethe presentation format
export function convertPdfToB1Topic(item) {
  const fullText = `${item.einleitungDe} ${item.strukturDe}\n\n${item.erfahrungDe}\n\n${item.heimatDe}\n\n${item.vorteileDe} ${item.nachteileDe}\n\n${item.meinungDe}\n\n${item.schlussDe}`;
  const fullTextEn = `${item.einleitungEn} ${item.strukturEn}\n\n${item.erfahrungEn}\n\n${item.heimatEn}\n\n${item.vorteileEn} ${item.nachteileEn}\n\n${item.meinungEn}\n\n${item.schlussEn}`;

  return {
    id: item.id,
    number: item.number,
    title: item.title,
    titleEn: item.titleEn,
    question: item.question,
    category: item.category,
    badge: item.badge,
    fullText,
    fullTextEn,
    wordCount: item.wordCount,
    estTime: item.estTime,
    slides: [
      {
        slide: 1,
        title: "Folie 1: Thema & Struktur",
        titleEn: "Slide 1: Topic & Structure",
        objective: "Thema nennen und die 4 Teile der Präsentation klar ankündigen.",
        notes: [
          `Thema: ${item.title.replace(/^\d+\.\s*/, '')}`,
          "4 Teile: Eigene Erfahrung, Heimatland, Vor-/Nachteile, Meinung"
        ],
        textDe: `${item.einleitungDe} ${item.strukturDe}`,
        textEn: `${item.einleitungEn} ${item.strukturEn}`,
        speak: `${item.einleitungDe} ${item.strukturDe}`,
        usefulPhrases: ["Das Thema meiner Präsentation ist...", "Meine Präsentation hat vier Teile:", "Zuerst möchte ich..."]
      },
      {
        slide: 2,
        title: "Folie 2: Persönliche Erfahrungen",
        titleEn: "Slide 2: Personal Experience",
        objective: "Von eigenen persönlichen Erfahrungen und Erlebnissen im Alltag berichten.",
        notes: [
          "Persönliche Erfahrung aus Schule / Beruf / Alltag",
          item.erfahrungDe.slice(0, 50) + "..."
        ],
        textDe: item.erfahrungDe,
        textEn: item.erfahrungEn,
        variantDe: item.erfahrungAltDe || null,
        variantEn: item.erfahrungAltEn || null,
        speak: item.erfahrungDe,
        usefulPhrases: ["Was meine persönlichen Erfahrungen angeht...", "In meinem Alltag...", "Als ich jünger war..."]
      },
      {
        slide: 3,
        title: "Folie 3: Situation im Heimatland",
        titleEn: "Slide 3: Situation in Home Country",
        objective: "Die Lage und Gewohnheiten im Heimatland beschreiben und vergleichen.",
        notes: [
          "Situation in Kenia / Heimatland",
          "Traditionen vs. moderne Trends in den Städten"
        ],
        textDe: item.heimatDe,
        textEn: item.heimatEn,
        variantDe: item.heimatAltDe || null,
        variantEn: item.heimatAltEn || null,
        speak: item.heimatDe,
        usefulPhrases: ["In meinem Heimatland ist es so, dass...", "Bei uns in Kenia...", "Besonders junge Leute..."]
      },
      {
        slide: 4,
        title: "Folie 4: Vor- und Nachteile mit Beispielen",
        titleEn: "Slide 4: Advantages & Disadvantages with Examples",
        objective: "Beide Seiten differenziert abwägen und konkrete Beispiele anführen.",
        notes: [
          "Vorteile: Positiver Nutzen für Mensch und Gesellschaft",
          "Nachteile: Kosten, Risiken oder gesundheitliche Folgen"
        ],
        vorteileDe: item.vorteileDe,
        vorteileEn: item.vorteileEn,
        nachteileDe: item.nachteileDe,
        nachteileEn: item.nachteileEn,
        textDe: `${item.vorteileDe} ${item.nachteileDe}`,
        textEn: `${item.vorteileEn} ${item.nachteileEn}`,
        speak: `${item.vorteileDe} ${item.nachteileDe}`,
        usefulPhrases: ["Ein großer Vorteil ist...", "Auf der anderen Seite...", "Ein Nachteil ist, dass..."]
      },
      {
        slide: 5,
        title: "Folie 5: Eigene Meinung & Abschluss",
        titleEn: "Slide 5: Personal Opinion & Conclusion",
        objective: "Eigene Meinung begründen, zusammenfassen und Dank aussprechen.",
        notes: [
          "Persönliche Meinung & Empfehlung",
          "Zusammenfassung & Dank an die Prüfer"
        ],
        textDe: `${item.meinungDe} ${item.schlussDe}`,
        textEn: `${item.meinungEn} ${item.schlussEn}`,
        speak: `${item.meinungDe} ${item.schlussDe}`,
        usefulPhrases: ["Meiner Meinung nach...", "Zusammenfassend kann ich sagen...", "Vielen Dank für Ihre Aufmerksamkeit!"]
      }
    ],
    qa: [
      {
        asker: "Gesprächspartner/in",
        questionDe: `Wie denken deine Freunde und deine Familie über dieses Thema?`,
        questionEn: `How do your friends and family feel about this topic?`,
        modelAnswerDe: `In meiner Familie gibt es unterschiedliche Meinungen: Die ältere Generation sieht das traditioneller, während meine Freunde die modernen Möglichkeiten bevorzugen.`,
        modelAnswerEn: `In my family there are different opinions: the older generation sees it more traditionally, while my friends prefer the modern opportunities.`
      },
      {
        asker: "Prüfer/in",
        questionDe: `Welchen Rat würden Sie jemandem geben, der vor dieser Entscheidung steht?`,
        questionEn: `What advice would you give to someone facing this decision?`,
        modelAnswerDe: `Ich würde empfehlen, die Vor- und Nachteile genau abzuwägen und sich nicht unter Druck setzen zu lassen. Ein ausgewogener Mittelweg ist meistens das Beste.`,
        modelAnswerEn: `I would recommend weighing pros and cons carefully without letting oneself be pressured. A balanced middle ground is usually best.`
      }
    ]
  };
}

